+  font-size:13px;
+  color: var(--text);
+  transition: background .18s ease, transform .12s ease, box-shadow .18s ease;
+}
+.tab:hover{transform: translateY(-1px); box-shadow: 0 10px 24px rgba(29,29,31,.08)}
