+  position:sticky;
+  top: var(--nav-h);
+  z-index: 40;
+  background: rgba(245,245,247,.88);
+  backdrop-filter: blur(14px);
+  border-bottom: 1px solid rgba(29,29,31,.10);
+}
+.subnav-row{display:flex; gap:10px; overflow:auto; padding:10px 0}
