+.quick-links a:hover{box-shadow: 0 10px 24px rgba(29,29,31,.08); text-decoration:none}
+
+footer{
+  padding:34px 0;
+  background:#fff;
+  border-top:1px solid rgba(29,29,31,.10);
+}
+.footer-grid{display:grid; grid-template-columns: 1fr; gap:14px}
+.footer-section{border-top:1px solid rgba(29,29,31,.08); padding-top:12px}
+.footer-head{display:flex; align-items:center; justify-content:space-between; gap:10px; width:100%; background:transparent; border:none; padding:10px 0; cursor:pointer; font-size:14px; color: var(--text); text-align:left}
+.footer-links{display:grid; gap:8px; padding: 4px 0 12px}
+.footer-links a{color: var(--muted); font-size:13px}
+.legal{margin-top:18px; color: var(--muted); font-size:12px; line-height:1.45}
+
+@media (min-width: 720px){
+  .grid-tiles{grid-template-columns: 1fr 1fr}
+  .tile{min-height: 360px}
+  .tile .tile-top{max-width:52%}
+  .hero h1{font-size:56px}
+  .footer-grid{grid-template-columns: repeat(4, 1fr); gap:20px}
+  .footer-section{border-top:none; padding-top:0}
+  .footer-head{padding:0 0 10px; cursor:default}
+  .footer-head .chev{display:none}
+  .footer-links{display:grid !important; padding: 0}
+}
+
+@media (max-width: 719px){
+  .nav-links{display:none}
+  .carousel-nav.prev{left:0}
+  .carousel-nav.next{right:0}
+}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0}
+
*** End Patch
PATCH

